nextflow_process {

    name "Test Process PORECHOP_PORECHOP"
    script "../main.nf"
    process "PORECHOP_PORECHOP"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "porechop"
    tag "porechop/porechop"

    test("sarscov2 - nanopore - fastq") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/nanopore/fastq/test.fastq.gz', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out, unstableKeys:["log"])).match() }
            )
        }
    }

    test("sarscov2 - nanopore - fastq -- stub") {
        options "-stub"
        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/nanopore/fastq/test.fastq.gz', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}
